<?php get_header(); ?><main id="main" class="container page-main"><div class="content-layout"><div class="primary-content"><?php while(have_posts()):the_post(); ?><article <?php post_class('article-single'); ?>><div class="article-heading"><div class="article-cats"><?php the_category(' • '); ?></div><h1><?php the_title(); ?></h1><div class="article-byline"><?php echo esc_html(get_the_date()); ?> · <?php the_author_posts_link(); ?></div><?php $rating=get_post_meta(get_the_ID(),'_gamezone_rating',true);if($rating!=='')echo '<div class="review-score">★ '.esc_html(number_format_i18n((float)$rating,1)).'<small>/10</small></div>'; ?></div><?php if(has_post_thumbnail()): ?><div class="article-cover"><?php the_post_thumbnail('large'); ?></div><?php endif; ?><div class="article-content entry-content"><?php the_content();wp_link_pages(); ?></div><div class="article-tags"><?php the_tags('',' ',''); ?></div></article><nav class="post-neighbors" aria-label="<?php esc_attr_e('Outras matérias','gamezone'); ?>"><?php previous_post_link('%link','← %title');next_post_link('%link','%title →'); ?></nav><?php if(comments_open()||get_comments_number())comments_template();endwhile; ?></div><?php get_sidebar(); ?></div></main><?php get_footer(); ?>